    const m = /.{0,60}(\bundefined\b(?! name)|\[object Object\]|\bNaN\b).{0,60}/.exec(p)   // the manifest's own text speaks of an undefined name
    if (m) probs.push(c.label + ' prompt holds: ' + JSON.stringify(m[0]))

